package at.pinzker.taskloop;
import android.app.*;import android.content.*;import android.media.*;import android.net.Uri;import android.os.*;import java.util.*;
public class AlarmSoundService extends Service {
 static final String STOP="at.pinzker.taskloop.STOP_SOUND";static final int FOREGROUND=900000;
 final Map<Integer,Session> sessions=new HashMap<>();Handler handler=new Handler(Looper.getMainLooper());AudioManager audio;AudioFocusRequest focus;int previousVolume=-1,setVolume=-1;boolean focusHeld;
 class Session {MediaPlayer player;long start;boolean ready;int mode;Session(int m){mode=m;}}
 BroadcastReceiver stop=new BroadcastReceiver(){public void onReceive(Context c,Intent i){stopSound(i.getIntExtra("id",-1));}};
 public static void start(Context c,int id){c.startForegroundService(new Intent(c,AlarmSoundService.class).putExtra("id",id));}
 public static void stop(Context c,int id){c.sendBroadcast(new Intent(STOP).setPackage(c.getPackageName()).putExtra("id",id));}
 public void onCreate(){super.onCreate();audio=getSystemService(AudioManager.class);if(Build.VERSION.SDK_INT>=33)registerReceiver(stop,new IntentFilter(STOP),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(stop,new IntentFilter(STOP));NotificationChannel channel=new NotificationChannel("taskloop_playback","TaskLoop",NotificationManager.IMPORTANCE_LOW);channel.setSound(null,null);getSystemService(NotificationManager.class).createNotificationChannel(channel);}
 public int onStartCommand(Intent intent,int flags,int startId){Notification status=new Notification.Builder(this,"taskloop_playback").setSmallIcon(R.drawable.ic_notify).setContentTitle("TaskLoop").setContentText(L.english(this)?"Reminder sound active":"Erinnerungston aktiv").setCategory(Notification.CATEGORY_SERVICE).setOngoing(true).setContentIntent(PendingIntent.getActivity(this,900001,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT)).build();startForeground(FOREGROUND,status);if(intent==null){if(sessions.isEmpty())stopSelf();return START_NOT_STICKY;}int id=intent.getIntExtra("id",-1);Task t=Store.get(this,id);if(t==null||!t.active||t.last==0||t.alarmMode==AlarmRules.NOTIFICATION){if(sessions.isEmpty())stopSelf();return START_NOT_STICKY;}if(sessions.containsKey(id))return START_NOT_STICKY;
 boolean soundEnabled=Store.prefs(this).getBoolean("sound_enabled",false);boolean vibrationEnabled=Store.prefs(this).getBoolean("alarm_vibrate",false);if(!soundEnabled&&!vibrationEnabled){if(sessions.isEmpty())stopSelf();return START_NOT_STICKY;}
 AudioAttributes attributes=new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build();if(soundEnabled&&!focusHeld){focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN_TRANSIENT).setAudioAttributes(attributes).setOnAudioFocusChangeListener(change->{if(change==AudioManager.AUDIOFOCUS_LOSS){releaseAll();stopSelf();}else if(change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT){for(Session x:sessions.values())if(x.ready)x.player.pause();}else if(change==AudioManager.AUDIOFOCUS_GAIN){for(Session x:sessions.values())if(x.ready)x.player.start();}}).build();focusHeld=audio.requestAudioFocus(focus)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED;if(!focusHeld){Store.log(this,"Audio focus unavailable: #"+id);stopSelf();return START_NOT_STICKY;}previousVolume=audio.getStreamVolume(AudioManager.STREAM_ALARM);setVolume=audio.getStreamMaxVolume(AudioManager.STREAM_ALARM);try{audio.setStreamVolume(AudioManager.STREAM_ALARM,setVolume,0);}catch(SecurityException e){Store.log(this,"Alarm volume restricted by Android");}}
 Session session=new Session(t.alarmMode);sessions.put(id,session);if(vibrationEnabled)try{getSystemService(Vibrator.class).vibrate(VibrationEffect.createWaveform(new long[]{0,250,1750},0));}catch(Exception ignored){}if(soundEnabled){String selected=Store.prefs(this).getString("sound_uri","");prepare(id,session,selected.isEmpty()?RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM):Uri.parse(selected),attributes,false);}return START_NOT_STICKY;}
 void prepare(int id,Session s,Uri uri,AudioAttributes attrs,boolean fallback){if(sessions.get(id)!=s)return;try{MediaPlayer p=new MediaPlayer();s.player=p;p.setAudioAttributes(attrs);p.setWakeMode(this,PowerManager.PARTIAL_WAKE_LOCK);p.setDataSource(this,uri);p.setLooping(true);float initial=level(s,0);p.setVolume(initial,initial);p.setOnPreparedListener(mp->{if(sessions.get(id)!=s){mp.release();return;}s.ready=true;s.start=SystemClock.elapsedRealtime();mp.start();handler.removeCallbacks(ramp);handler.post(ramp);Store.log(this,"Alarmton gestartet: #"+id);});p.setOnErrorListener((mp,what,extra)->{mp.release();s.ready=false;if(!fallback)prepare(id,s,RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION),attrs,true);else{Store.log(this,"Alarm sound failed: #"+id);stopSound(id);}return true;});p.prepareAsync();}catch(Exception e){if(s.player!=null){s.player.release();s.player=null;}if(!fallback)prepare(id,s,RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION),attrs,true);else{Store.log(this,"Alarm sound unavailable: #"+id);stopSound(id);}}}
 float level(Session s,long elapsed){android.content.SharedPreferences p=Store.prefs(this);return AlarmRules.volume(elapsed,p.getInt("fade_seconds",30)*1000L,p.getInt("sound_start",1),p.getInt("sound_target",100),s.mode!=AlarmRules.LOUD&&p.getBoolean("sound_fade",true));}
 Runnable ramp=new Runnable(){public void run(){for(Session s:new ArrayList<>(sessions.values()))if(s.ready&&s.player!=null){float v=level(s,SystemClock.elapsedRealtime()-s.start);s.player.setVolume(v,v);}if(!sessions.isEmpty())handler.postDelayed(this,100);}};
 void stopSound(int id){Session s=sessions.remove(id);if(s!=null&&s.player!=null)s.player.release();if(sessions.isEmpty()){releaseAll();stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}}
 void releaseAll(){handler.removeCallbacksAndMessages(null);for(Session s:sessions.values())if(s.player!=null)s.player.release();sessions.clear();getSystemService(Vibrator.class).cancel();if(focusHeld&&focus!=null){audio.abandonAudioFocusRequest(focus);focusHeld=false;}if(previousVolume>=0&&audio.getStreamVolume(AudioManager.STREAM_ALARM)==setVolume)try{audio.setStreamVolume(AudioManager.STREAM_ALARM,previousVolume,0);}catch(SecurityException ignored){}previousVolume=-1;}
 public void onDestroy(){releaseAll();try{unregisterReceiver(stop);}catch(Exception ignored){}super.onDestroy();}public IBinder onBind(Intent i){return null;}
}
